import{_ as t,c as o,a,b as p,d as n,e as c,w as l,r as i,o as r}from"./app-DuzDMLLM.js";const d="/assets/atomic-D72Xa1LT.png",k={};function u(m,s){const e=i("RouteLink");return r(),o("div",null,[s[2]||(s[2]=a(`<blockquote><p>TaskType对应一个TaskBooks，多个TaskBooks组合成一个Task。不同的Task存在在原子任务中心的<code>TaskMap</code>中以TaskID作为键来进行存储，TaskID的获取方式是通过函数<code>AddTask</code>的返回值获取的。</p></blockquote><h1 id="原子任务中心的作用" tabindex="-1"><a class="header-anchor" href="#原子任务中心的作用"><span>原子任务中心的作用</span></a></h1><p>当客户端发来<span style="color:#0099FF;"><code>miql</code></span>之后，misakadb要统一进行解析，为了保持miql的任务的原子性、一致性、隔离性、持久性这四个属性，misakaDB需要一个原子任务中心来管理所有的任务。</p><blockquote><p>如当用户发送一个删除任务，这个任务拆分下来就是需要对文件、JSON等进行删除的多个子任务。这些任务需要保证要么不执行要么全部执行。</p></blockquote><p>所以我们执行多个需要多步骤的任务不能直接进行执行，而是把子任务一次性追加到我们的新任务中。</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">atomic <span class="token operator">:=</span> atomic_work_center<span class="token punctuation">.</span><span class="token function">GetAtomicWorkCenter</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 创建一个原子任务中心</span></span>
<span class="line">task <span class="token operator">=</span> atomic_work_center<span class="token punctuation">.</span><span class="token function">NewTask</span><span class="token punctuation">(</span><span class="token boolean">nil</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 创建一个空任务</span></span>
<span class="line">task<span class="token punctuation">.</span>TaskBooks <span class="token operator">=</span> tasktype<span class="token punctuation">.</span><span class="token function">NewShipBuilder</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">.</span><span class="token function">Add</span><span class="token punctuation">(</span>tasktype<span class="token punctuation">.</span>TaskModFile<span class="token punctuation">,</span> <span class="token string">&quot;xxx.filename.txt&quot;</span><span class="token punctuation">)</span></span>
<span class="line">	<span class="token punctuation">.</span><span class="token function">Build</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">;</span></span>
<span class="line"><span class="token comment">// 构建一个任务体，任务体包含需要原子执行的多个任务子作业</span></span>
<span class="line"></span>
<span class="line">ok<span class="token punctuation">,</span> task_id <span class="token operator">:=</span> atomic<span class="token punctuation">.</span><span class="token function">addTask</span><span class="token punctuation">(</span>task<span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span> <span class="token comment">// 尝试添加任务到原子中心 可以重试3次</span></span>
<span class="line"><span class="token comment">// ok: 表示是否添加成功</span></span>
<span class="line"><span class="token comment">// task_id: 表示任务在中心的唯一标志</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h1 id="原子日志序列器-json" tabindex="-1"><a class="header-anchor" href="#原子日志序列器-json"><span>原子日志序列器(JSON)</span></a></h1><p><span style="color:#0099FF;"><strong>AtomicWorkCenter</strong></span> 管理着所有的任务，我们将这些任务数据可以称为WAL日志。防止宕机等问题导致的数据丢失，我们会在启动之后启动对应的序列器协程。如果需要让协程启动序列化任务可以使用AtomicWorkEventBus总线进行信号通知。</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">var</span> eb <span class="token operator">*</span>eventbus<span class="token punctuation">.</span>AtomicWorkEventBus</span>
<span class="line">eb <span class="token operator">=</span> eventbus<span class="token punctuation">.</span><span class="token function">GetAtomicWorkCenterEventBus</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">eb<span class="token punctuation">.</span>EventBus <span class="token operator">&lt;-</span> <span class="token string">&quot;sync-to-local&quot;</span> <span class="token comment">// 通知序列器协程启动序列化任务</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>我们也可以加载本地WAL日志到内存:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">workCenterSerializer <span class="token operator">:=</span> atomic_work_center<span class="token punctuation">.</span><span class="token function">LoadWorkCenterSerializer</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>WAL的日志默认储存路径是：<code>.data/work_center.json</code> ， 如果日志大于1MB的时候，系统会对其进行分片存储。atomic_work_center的本质就是 WAL日志的记录。</p><h1 id="原子日志序列器-ndjson" tabindex="-1"><a class="header-anchor" href="#原子日志序列器-ndjson"><span>原子日志序列器(NDJSON)</span></a></h1><div class="hint-container warning"><p class="hint-container-title">Warning</p><p>当前版本截至，该开发计划还在排队中, 对项目进度有兴趣的可以查看：<a href="http://blog.6ugo.cn/?view=projects&amp;project=c678ce4e-63c7-49b6-8cd1-4bb3d9b36872" target="_blank" rel="noopener noreferrer">点击跳转</a></p></div><h1 id="原子任务中心结构" tabindex="-1"><a class="header-anchor" href="#原子任务中心结构"><span>原子任务中心结构</span></a></h1><p>原子中心有一个map，map管理了多个task，task管理了多个TaskBooks，也就是作业本。</p><p>原子任务中心维护了一个TasksMap，其主要目的是用于管理存储所有的任务。其map数据结构为：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token operator">*</span>xsync<span class="token punctuation">.</span>MapOf<span class="token punctuation">[</span><span class="token builtin">string</span><span class="token punctuation">,</span> <span class="token operator">*</span>Task<span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>键表示任务的唯一标志，值表示任务体指针。Task是任务体结构，包含多个作业本。 举一个例子，当我们添加一个任务的时候：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line">center <span class="token operator">:=</span> atomic_work_center<span class="token punctuation">.</span><span class="token function">GetAtomicWorkCenter</span><span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">ok<span class="token punctuation">,</span> task_id <span class="token operator">:=</span> center<span class="token punctuation">.</span><span class="token function">AddTask</span><span class="token punctuation">(</span>task<span class="token punctuation">,</span> <span class="token number">3</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div></div></div><p>AddTask方式会返回两个值：</p><ul><li>boolean 表示是否添加成功</li><li>string 表示任务在中心的唯一标志</li></ul><p><img src="`+d+`" alt="atomic"></p><h2 id="taskbooks" tabindex="-1"><a class="header-anchor" href="#taskbooks"><span>TaskBooks</span></a></h2><p>TaskBooks是任务的作业本，一个任务由多个作业组成，每个作业表示的是一个细分的操作，通过 TaskType 进行指定作业内容。 可见源码如下：</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">const</span> <span class="token punctuation">(</span></span>
<span class="line">	TaskRemoveFile   TaskType <span class="token operator">=</span> <span class="token string">&quot;remove_file&quot;</span></span>
<span class="line">	TaskModFile      TaskType <span class="token operator">=</span> <span class="token string">&quot;mod_file&quot;</span></span>
<span class="line">	TaskRemoveFolder TaskType <span class="token operator">=</span> <span class="token string">&quot;remove_folder&quot;</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">type</span> TaskBooks <span class="token keyword">struct</span> <span class="token punctuation">{</span></span>
<span class="line">	TaskType TaskType</span>
<span class="line">	Params   <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span></span>
<span class="line"><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="taskbooks的执行和回滚" tabindex="-1"><a class="header-anchor" href="#taskbooks的执行和回滚"><span>TaskBooks的执行和回滚</span></a></h3><h4 id="执行" tabindex="-1"><a class="header-anchor" href="#执行"><span>执行</span></a></h4><p>执行作业本的方式是采用<code>原子任务中心</code>，首先需要把<code>作业本</code>挂载到指定的Task上，然后通过addTask将Task添加到原子任务中心。添加了任务之后，就可以使用原子任务中心的如下方法进行执行了。</p><h5 id="执行的方式" tabindex="-1"><a class="header-anchor" href="#执行的方式"><span>执行的方式</span></a></h5><ul><li><code>DoNext</code>: 执行下一个作业;</li><li><code>DoSustain</code>: 从任务执行位置开始继续执行作业;</li></ul><div class="hint-container tip"><p class="hint-container-title">Misaka 提醒你</p><p>Task有一个属性叫做TaskCurrentIndex， 用于记录当前的任务的执行位置的，当启动服务之后这个位置不是0状态也不是over的时候表示这个任务可能在执行中途，服务器宕机了。</p></div><h2 id="tasktype" tabindex="-1"><a class="header-anchor" href="#tasktype"><span>TaskType</span></a></h2>`,33)),p("p",null,[s[1]||(s[1]=n("TaskType主要是区别这个TaskBook是做什么的，不同的TaskType对应不同的TaskTypeAction和TaskTypeRoll两个函数。TaskType全部都是通过插件进行注册的，想要对TaskType开发相关进行了解，可以前往插件开发进行查看。",-1)),c(e,{to:"/posts/article3.html"},{default:l(()=>[...s[0]||(s[0]=[n("点击跳转",-1)])]),_:1})]),s[3]||(s[3]=a(`<h3 id="tasktypeaction" tabindex="-1"><a class="header-anchor" href="#tasktypeaction"><span>TaskTypeAction</span></a></h3><p>一个<code>Tasktype</code>对应一个<code>TasktypeAction</code>，Donext函数等执行函数会通过<code>TaskBooks</code>的Tasktype找到对应的<code>TaskTypeAction</code>, 然后进行执行。<code>TaskTypeAction</code> 的签名是:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">type</span> FuncTaskTypeAction <span class="token operator">=</span> <span class="token keyword">func</span><span class="token punctuation">(</span>taskType tasktype<span class="token punctuation">.</span>TaskType<span class="token punctuation">,</span> params <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token builtin">error</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>params 就是TaskBook的属性 <code>Params</code>。</p><h3 id="tasktyperoll" tabindex="-1"><a class="header-anchor" href="#tasktyperoll"><span>TaskTypeRoll</span></a></h3><p>和 TaskTypeAction 一样， 都是执行函数，只是本函数主要是对事件进行回滚的时候再触发。<code>TaskTypeRoll</code>的签名是:</p><div class="language-go line-numbers-mode" data-highlighter="prismjs" data-ext="go"><pre><code><span class="line"><span class="token keyword">type</span> FuncTaskTypeRoll <span class="token operator">=</span> <span class="token keyword">func</span><span class="token punctuation">(</span>taskType tasktype<span class="token punctuation">.</span>TaskType<span class="token punctuation">,</span> params <span class="token punctuation">[</span><span class="token punctuation">]</span><span class="token builtin">string</span><span class="token punctuation">)</span> <span class="token builtin">error</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="taskcombo-v0-1-8" tabindex="-1"><a class="header-anchor" href="#taskcombo-v0-1-8"><span>TaskCombo (V0.1.8)</span></a></h3><blockquote><p>0.1.8新增内容</p></blockquote><p><code>Combo</code> 有连招之译，<code>TaskCombo</code> 就是对一个完整的业务进行打包组合成一个特殊的Task, 如：删除数据库、查询数据库等。</p><h5 id="插件支持" tabindex="-1"><a class="header-anchor" href="#插件支持"><span>插件支持</span></a></h5><p>任务中心支持用户自定义作业本的执行方式，用户可以通过实现<code>TaskBooks</code>的<code>TaskType</code>来定义自己的作业类型。你可以查看文档进行实现插件。当前所有TaskType的功能实现都是插件支持的。</p>`,12))])}const b=t(k,[["render",u]]),v=JSON.parse('{"path":"/posts/article2.html","title":"原子任务中心","lang":"en-US","frontmatter":{"date":"2026-07-02T00:00:00.000Z","title":"原子任务中心","category":["内部实现"],"tag":["原子任务"],"description":"原子任务中心介绍"},"headers":[{"level":2,"title":"TaskBooks","slug":"taskbooks","link":"#taskbooks","children":[{"level":3,"title":"TaskBooks的执行和回滚","slug":"taskbooks的执行和回滚","link":"#taskbooks的执行和回滚","children":[]}]},{"level":2,"title":"TaskType","slug":"tasktype","link":"#tasktype","children":[{"level":3,"title":"TaskTypeAction","slug":"tasktypeaction","link":"#tasktypeaction","children":[]},{"level":3,"title":"TaskTypeRoll","slug":"tasktyperoll","link":"#tasktyperoll","children":[]},{"level":3,"title":"TaskCombo (V0.1.8)","slug":"taskcombo-v0-1-8","link":"#taskcombo-v0-1-8","children":[]}]}],"git":{"updatedTime":1787533364000,"contributors":[{"name":"hello_kuma","username":"","email":"2791528600@qq.com","commits":5},{"name":"库玛","username":"","email":"2791528600@qq.com","commits":3}],"changelog":[{"hash":"9f184c10282347dbacf5f10f9fd66c18a1d766a4","time":1787533364000,"email":"2791528600@qq.com","author":"库玛","message":"fix: Windows中，部分场景下，删除数据库无权限的提醒。"},{"hash":"83bb2a6d309049c38bd1f678081e3169d712184a","time":1786240905000,"email":"2791528600@qq.com","author":"库玛","message":"v0.1.8  更新 WIP"},{"hash":"14a13f38f2e1ac08fc266da7c5283fed3f8eb6ca","time":1786192716000,"email":"2791528600@qq.com","author":"库玛","message":"文档更新项目进入0.1.8状态(WIP)"},{"hash":"6d0d5738737eded2c5745c8bfe17c84049e71350","time":1782989277000,"email":"2791528600@qq.com","author":"hello_kuma","message":"refactor(atomic-work-center): 重构任务中心字段命名并完善文档"},{"hash":"d1de821ae57c54a858455988ddcfc8f598f2867d","time":1782286368000,"email":"2791528600@qq.com","author":"hello_kuma","message":"feat(atomic, docs): 新增原子分块文件写入能力，完善项目文档"},{"hash":"7fc80838e84c201e900ffe0f4ff31ca91f0cdad6","time":1782207557000,"email":"2791528600@qq.com","author":"hello_kuma","message":"docs: 完善项目文档，新增原子分块文件写入能力"},{"hash":"418d98b8ab2796f538e547cbada0e4acc21f5e01","time":1782178263000,"email":"2791528600@qq.com","author":"hello_kuma","message":"更新文档内容"},{"hash":"7736ed0f48124c7effc08095f47f9f31145d334b","time":1782123339000,"email":"2791528600@qq.com","author":"hello_kuma","message":"1"}]},"filePathRelative":"posts/article2.md","excerpt":"<blockquote>\\n<p>TaskType对应一个TaskBooks，多个TaskBooks组合成一个Task。不同的Task存在在原子任务中心的<code>TaskMap</code>中以TaskID作为键来进行存储，TaskID的获取方式是通过函数<code>AddTask</code>的返回值获取的。</p>\\n</blockquote>\\n<h1>原子任务中心的作用</h1>\\n<p>当客户端发来<span style=\\"color:#0099FF\\"><code>miql</code></span>之后，misakadb要统一进行解析，为了保持miql的任务的原子性、一致性、隔离性、持久性这四个属性，misakaDB需要一个原子任务中心来管理所有的任务。</p>"}');export{b as comp,v as data};
